; UFO-2: the boot loader for a plain TR-DOS disk (replaces XBSTART.A80 of 1996, see src/original/xbstart.asm).
;
; BASIC "boot":  CLEAR 24575: RANDOMIZE USR 15619: REM : LOAD "ufo2" CODE : RANDOMIZE USR 24576
; The loader shows the title program, then starts the intro, the manual or the game - the same sequence as in 1996,
; but the files are read with the TR-DOS call "read sectors" (C=5, #3D13) from the places listed in
; build/boot_layout.inc (generated by build.py), and nothing is checked or decoded.
;
; All files but "page0" are packed with ZX0 (word length + stream, tools/zx0.py). Where a file is loaded to is in
; the table too:
;   - 16K pages and other blocks for #C000..: loaded to the buffer BUF and unpacked from there;
;   - programs for #7000 (title, manual, intro): loaded to the top of the free memory and unpacked downwards over
;     themselves (build.py checks that this is safe);
;   - the game (#4000..): loaded to #9200 and unpacked by a small last stage that sits in page 6.

	DEVICE ZXSPECTRUM128
	ORG	#6000

DSCR	EQU	#4000
SCR	EQU	#C000
STACK	EQU	#6F00
BUF	EQU	#7000		; buffer for packed pages (up to #BFFF)
PROG	EQU	#7000		; title, manual and intro run here
MAINLD	EQU	#9200		; the packed game is loaded here, behind the place it is unpacked to
GAME0	EQU	#4000		; the game: #4000..#90FF
STUBAD	EQU	#FF00		; the last stage runs here (page 6)

START	DI
	IM	1
	LD	SP,STACK
	LD	IY,#5C3A
	LD	A,(#5CF6)	; the drive TR-DOS booted from
	LD	(DRIVE),A
MENU	DI
	LD	SP,STACK
	XOR	A
	OUT	(254),A
	CALL	OFFD
	CALL	OFFS
	CALL	MEM0
	LD	A,F_TITLE
	CALL	LOADP
	CALL	PROG
	DI
	CP	1		; what was pressed: 0 intro, 1 game, 2 manual
	JP	Z,GAME
	JP	C,INTRO
;------------
INSTR	CALL	MEM7
	LD	A,F_MANUAL7	; the pictures of the manual, page 7
	LD	DE,#DB00
	CALL	LOADU
	CALL	MEM0
	LD	A,F_MANUAL
	CALL	LOADP
	CALL	PROG
	JP	MENU
;-----------
INTRO	LD	HL,INTTAB	; the pictures: page, file
	LD	B,6
INT1	LD	A,(HL)
	INC	HL
	CALL	MEMS
	LD	A,(HL)
	INC	HL
	PUSH	HL
	PUSH	BC
	CALL	LOADG
	POP	BC
	POP	HL
	DJNZ	INT1
	XOR	A
	CALL	MEMS
	LD	A,F_INTRO
	CALL	LOADP
	CALL	OFFD
	CALL	PROG
	DI
	LD	A,7
	CALL	MEMS
	CALL	OFFS_
	JP	MENU
INTTAB	DEFB	1,F_DEMO0, 4,F_DEMO1, 0,F_DEMO2, 6,F_DEMOS6, 7,F_DEMOS7, 3,F_DEMOTXT
;-------------
GAME	DI
	CALL	OFFD
	CALL	OFFS
	LD	A,7
	CALL	MEMS
	LD	A,F_PAGE7
	CALL	LOADG
	CALL	MEM0		; from here the second screen (page 7) is shown: the "history" picture
	LD	A,F_PAGE0
	CALL	LOADF		; page 0 is not packed (it holds the packed overlays)
	LD	A,1
	CALL	MEM
	LD	A,F_PAGE1
	CALL	LOADG
	LD	A,3
	CALL	MEM
	LD	A,F_PAGE3
	CALL	LOADG
	LD	A,4
	CALL	MEM
	LD	A,F_PAGE4
	CALL	LOADG
	LD	A,6
	CALL	MEM
	LD	A,F_MAIN
	CALL	LOADF
	DI
	LD	HL,STUB
	LD	DE,STUBAD
	LD	BC,STUBE-STUB
	LDIR
	LD	A,(DRIVE)
	JP	STUBAD

; the last stage: unpack the game to #4000 (over this loader and the system variables) and start it
STUB	DISP	STUBAD
	LD	SP,STUBAD
	PUSH	AF
	LD	HL,MAINLD+2
	LD	DE,GAME0
	CALL	S.DELPC
	POP	AF
	LD	(DSKDRV),A	; tell the game its drive (address from build/boot_layout.inc)
	JP	GAME0+16
	MODULE	S
	INCLUDE "dzx0.asm"
	ENDMODULE
	ENT
STUBE

LOADP	LD	DE,PROG		; file A: a program for #7000
	JR	LOADU
LOADG	LD	DE,SCR		; file A: a 16K page
LOADU	PUSH	DE		; load file A and unpack it to DE
	CALL	LOADF
	POP	DE
	INC	HL
	INC	HL
	MODULE	L
	INCLUDE "dzx0.asm"
	ENDMODULE

; load file A (number F_xxx) to the address given in FTAB; returns HL = that address
LOADF	LD	L,A
	LD	H,0
	ADD	HL,HL
	ADD	HL,HL
	LD	DE,FTAB
	ADD	HL,DE
	LD	D,(HL)		; track
	INC	HL
	LD	E,(HL)		; sector 0..15
	INC	HL
	LD	B,(HL)		; number of sectors
	INC	HL
	LD	H,(HL)		; address / 256
	LD	L,0
	PUSH	HL
	LD	C,5
	LD	IY,#5C3A
	CALL	#3D13
	DI
	POP	HL
	RET

MEM0	XOR	A		; page A at #C000, the second screen shown
MEM	OR	%11000
	JR	MEMX
MEM7	LD	A,7
	JR	MEM
MEMS	OR	%10000		; page A at #C000, the normal screen shown
MEMX	PUSH	BC
	LD	BC,#7FFD
	OUT	(C),A
	POP	BC
	RET

OFFD	LD	DE,DSCR+#1AFE	; black screen: attributes 0, pixels set
	JR	OFFX
OFFS	CALL	MEM7
OFFS_	LD	DE,SCR+#1AFE
OFFX	LD	H,D
	LD	L,E
	INC	HL
	LD	BC,768
	LD	(HL),0
	LDDR
	LD	BC,6143
	LD	(HL),255
	LDDR
	RET

DRIVE	DEFB	0
	INCLUDE "boot_layout.inc"	; FTAB and the numbers F_xxx
BOOTEND
	ASSERT	BOOTEND <= STACK-#100
	SAVEBIN "boot.bin",#6000,BOOTEND-#6000
